        staa    >ChargeTempUnfiltered
        ldaa    >LastChargeTempVolts
        cmpa    >CHGHIG_ChargeTempOutOfRangeHigh     ; CHGHIG (ChargeTempOutOfRangeHigh)
        bhi     LE4F6
        cmpa    >CHGLOW_ChargeTempOutOfRangeLow      ; CHGLOW (ChargeTempOutOfRangeLow)
        bcs     LE4F6
        brset   <b58_IPL1,#$01,LE4F6
        ldy     #REGS
        brclr   $00,y,#$40,LE4C4                     ; PORTA: Port A data (timer pins: IC1-IC3, OC2-OC5, PAI)
        ldx     #TMPTL1_TempForColdScaleA2D          ; TMPTL1 (TempForColdScaleFromA2D)
        cmpa    #$40
        bcc     LE4E1
        ldab    <BitFlags6a
        bitb    #$C0
        beq     LE4BA
        addb    #$40
        stab    <BitFlags6a
        bra     LE4E4

LE4BA:
        andb    #$C0
        stab    <BitFlags6a
        bclr    $00,y,#$40
        bra     LE4F6

LE4C4:
        ldx     #TMPTL2_TempForHotScaleA2D           ; TMPTL2 (TempForHotScaleA2D)
        cmpa    #$DC
        bls     LE4E1
        ldab    <BitFlags6a
        bitb    #$C0
        beq     LE4D7
        addb    #$40
        stab    <BitFlags6a
        bra     LE4E4

LE4D7:
        andb    #$C0
        stab    <BitFlags6a
        bset    $00,y,#$40
        bra     LE4F6

LE4E1:
        bclr    <BitFlags6a,#$C0
LE4E4:
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        ldab    <ChargeTemp
        sba
        bcc     LE4EF
        decb
